  "[ \$(grep -c '    settings = DMBarSizeAerialWindowSettings(self, settings);' $S) = 2 ] && grep -qF 'if (gDMBarSize == MSBDMenuBarSmall || !(gDMMenuBarStockH > 0) || DMActiveEngine() != DMEngineAerial || !settings) return settings;' $S && grep -qF 'if (DMSceneFrameIsCanvas(f) || !(f.size.width >= 50.0) || !(f.size.height >= 50.0)) return settings;' $S && grep -qF 'if (!sm || strcmp(method_getTypeEncoding(sm) ?: \"\", \"v32@0:8d16q24\")) return settings;' $S && awk '/^- \\(void\\)updateSettings:\\(id\\)settings withTransitionContext:\\(id\\)context \\{/{f=1} f&&/settings = DMVetoFrameHoldApply/{a=NR} f&&/gFullFrameGuardBundle.length && CACurrentMediaTime\\(\\) < gFullFrameGuardUntil && \\[settings respondsToSelector/{b=NR} f&&/settings = DMBarSizeAerialWindowSettings\\(self, settings\\);/{c=NR; print (a&&b&&a<b&&b<c) ? \"ok\" : \"no\"; exit}' $S | grep -q ok"
