   && grep -qF 'if (!MSBDMenuBarHooksWanted(want, displays)) {' $S && grep -qF 'MSBDDispFlatIs(flat.UTF8String, \"msb\", kMSBDMenuBarSizeKey)' $S && grep -qF 'if ([master isKindOfClass:[NSNumber class]] && ![master boolValue]) return NO;' $S \
