  "awk '/^static int DMTVBarSizeNow\\(void\\) \\{/{f=1} f&&/if \\(gDMTVBarSize >= 0\\) return gDMTVBarSize;/{a=NR} f&&/if \\(!gDMBarHooksIn\\) return MSBDMenuBarSmall;/{b=NR} f&&/double n = DMDispNumForKey\\(key, \"msb\", kMSBDMenuBarSizeKey, -1.0, 0.0, 2.0\\);/{c=NR} f&&/gDMTVBarSize = MSBDMenuBarTVSizeAtConnect\\(1, hasOwn, own, gDMBarSize\\);/{d=NR} f&&/^}/{print (a&&b&&c&&d&&a<b&&b<c&&c<d) ? \"ok\" : \"no\"; exit}' $S | grep -q ok \
   && awk '/^static void DMBarSizeInstall\\(int want, BOOL late\\) \\{/{f=1} f&&/if \\(late && DMTVBarDisplayKey\\(\\)\\) gDMTVBarSize = MSBDMenuBarSmall;/{a=NR} f&&/    gDMBarHooksIn = YES;/{b=NR} f&&/UIScreenDidConnectNotification, UIScreenDidDisconnectNotification/{c=NR} f&&/            gDMTVBarSize = -1;/{d=NR} f&&/^}/{print (a&&b&&c&&d&&a<b&&c<d) ? \"ok\" : \"no\"; exit}' $S | grep -q ok"
